@import "@fontsource-variable/dm-sans";
@import "@fontsource-variable/newsreader/opsz.css";

/* Light (faithful): white paper, warm near-black ink (rgb 20,20,19), a warm caption grey
   (rgb 99,99,94), a charcoal button (rgb 33,32,28), warm greige photo placeholders and
   translucent warm-brown hairlines (rgba 25,21,1,.29). */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.2 0.003 106);
  --card: oklch(0.975 0.004 85);
  --card-foreground: oklch(0.2 0.003 106);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.2 0.003 106);
  --primary: oklch(0.245 0.008 95);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.965 0.006 85);
  --secondary-foreground: oklch(0.2 0.003 106);
  --muted: oklch(0.925 0.012 80);
  --muted-foreground: oklch(0.49 0.008 106);
  --accent: oklch(0.955 0.008 85);
  --accent-foreground: oklch(0.2 0.003 106);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.22 0.03 100 / 29%);
  --input: oklch(0.22 0.03 100 / 29%);
  --ring: oklch(0.2 0.003 106);
  --highlight: oklch(0.62 0.05 70);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.9 0.025 80);
  --chart-1: oklch(0.245 0.008 95);
  --chart-2: oklch(0.49 0.008 106);
  --chart-3: oklch(0.62 0.05 70);
  --chart-4: oklch(0.78 0.03 80);
  --chart-5: oklch(0.9 0.02 80);
  --sidebar: oklch(0.975 0.004 85);
  --sidebar-foreground: oklch(0.2 0.003 106);
  --sidebar-primary: oklch(0.245 0.008 95);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.955 0.008 85);
  --sidebar-accent-foreground: oklch(0.2 0.003 106);
  --sidebar-border: oklch(0.22 0.03 100 / 29%);
  --sidebar-ring: oklch(0.2 0.003 106);

  --typeface-body: "DM Sans Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Newsreader Variable", "Baskerville", Georgia, serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.125rem;
  --page-width: 120rem;
  --page-gutter: 0.9375rem;
  --section-y: 2.5rem;
}

/* From 1024px: the 17px gutter and the roomier ~5.5rem space above section headings. */
@media (min-width: 64rem) {
  :root {
    --page-gutter: 1.0625rem;
    --section-y: 5.5rem;
  }
}

/* Dark (sibling): warm black paper, ivory ink, a taupe caption grey, an ivory button. */
.dark {
  --background: oklch(0.17 0.004 95);
  --foreground: oklch(0.95 0.01 85);
  --card: oklch(0.21 0.005 95);
  --card-foreground: oklch(0.95 0.01 85);
  --popover: oklch(0.21 0.005 95);
  --popover-foreground: oklch(0.95 0.01 85);
  --primary: oklch(0.93 0.012 85);
  --primary-foreground: oklch(0.2 0.003 106);
  --secondary: oklch(0.23 0.006 95);
  --secondary-foreground: oklch(0.95 0.01 85);
  --muted: oklch(0.27 0.01 80);
  --muted-foreground: oklch(0.72 0.012 85);
  --accent: oklch(0.25 0.008 90);
  --accent-foreground: oklch(0.95 0.01 85);
  --destructive: oklch(0.65 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.95 0.02 85 / 22%);
  --input: oklch(0.95 0.02 85 / 25%);
  --ring: oklch(0.95 0.01 85);
  --highlight: oklch(0.75 0.05 75);
  --highlight-foreground: oklch(0.2 0.003 106);
  --glow: oklch(0.35 0.02 80);
  --chart-1: oklch(0.93 0.012 85);
  --chart-2: oklch(0.72 0.012 85);
  --chart-3: oklch(0.75 0.05 75);
  --chart-4: oklch(0.5 0.03 80);
  --chart-5: oklch(0.35 0.02 80);
  --sidebar: oklch(0.21 0.005 95);
  --sidebar-foreground: oklch(0.95 0.01 85);
  --sidebar-primary: oklch(0.93 0.012 85);
  --sidebar-primary-foreground: oklch(0.2 0.003 106);
  --sidebar-accent: oklch(0.25 0.008 90);
  --sidebar-accent-foreground: oklch(0.95 0.01 85);
  --sidebar-border: oklch(0.95 0.02 85 / 22%);
  --sidebar-ring: oklch(0.95 0.01 85);
}
